// Package db opens PostgreSQL connection pools. Queries live in package dbq,
// generated by sqlc from the migrations owned by packages/db.
package db

import (
	"context"
	"errors"
	"fmt"
	"time"

	"github.com/jackc/pgx/v5/pgxpool"
)

// Options tunes the pool. Zero values use the defaults noted on each field.
type Options struct {
	MaxConns          int32         // default 20
	MinConns          int32         // default 0
	MaxConnLifetime   time.Duration // default 1h
	HealthCheckPeriod time.Duration // default 30s
	ApplicationName   string        // shown in pg_stat_activity
}

// Open creates a pool for url and verifies that the server is reachable.
func Open(ctx context.Context, url string, opts Options) (*pgxpool.Pool, error) {
	cfg, err := pgxpool.ParseConfig(url)
	if err != nil {
		// The parse error can echo the URL, including its password.
		return nil, errors.New("parse database URL: invalid connection string")
	}
	cfg.MaxConns = valueOr(opts.MaxConns, 20)
	cfg.MinConns = opts.MinConns
	cfg.MaxConnLifetime = valueOr(opts.MaxConnLifetime, time.Hour)
	cfg.HealthCheckPeriod = valueOr(opts.HealthCheckPeriod, 30*time.Second)
	if opts.ApplicationName != "" {
		cfg.ConnConfig.RuntimeParams["application_name"] = opts.ApplicationName
	}
	// Timestamps are always handled in UTC; partition bounds are UTC days.
	cfg.ConnConfig.RuntimeParams["timezone"] = "UTC"

	pool, err := pgxpool.NewWithConfig(ctx, cfg)
	if err != nil {
		return nil, fmt.Errorf("create database pool: %w", err)
	}
	pingCtx, cancel := context.WithTimeout(ctx, 10*time.Second)
	defer cancel()
	if err := pool.Ping(pingCtx); err != nil {
		pool.Close()
		return nil, fmt.Errorf("connect to database: %w", err)
	}
	return pool, nil
}

func valueOr[T comparable](v, def T) T {
	var zero T
	if v == zero {
		return def
	}
	return v
}
